def find_in_grid(grid: list[list[int]], target: int) -> list[int]:
    if not grid:
        return [-1, -1]
    cols = len(grid[0])
    lo, hi = 0, len(grid) * cols          # half-open range over the flattened grid
    while lo < hi:
        mid = (lo + hi) // 2
        row, col = divmod(mid, cols)
        if grid[row][col] < target:
            lo = mid + 1
        else:
            hi = mid
    row, col = divmod(lo, cols)
    if lo < len(grid) * cols and grid[row][col] == target:
        return [row, col]
    return [-1, -1]
